#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn closed_inventory_binds_keys_and_physical_owners() {
        host_plan().unwrap();
        for dtype in shared::DTYPES {
            let mut owners = BTreeSet::new();
            for op in Operation::ALL {
                let r = baseline(dtype, op).unwrap();
                owners.insert(raw::work_items(r.parameters).unwrap());
                assert!(!r.trials[0].changed.is_empty());
                assert_ne!(r.trials[0].base, r.trials[1].base);
            }
            assert_eq!(owners, BTreeSet::from([127, 128, 129]));
            if dtype.is_int() || dtype.is_uint() {
                let sign = 1u64 << (dtype.size() * 8 - 1);
                for op in Operation::ALL {
                    let r = baseline(dtype, op).unwrap();
                    assert_ne!(bit_field(r.trials[1].base, dtype, 0) & sign, 0);
                }
                assert_eq!(bit_field(baseline(dtype, Operation::Add).unwrap().trials[0].expected, dtype, 3), 5);
            } else {
                for op in [Operation::Add, Operation::Mul] {
                    let r = baseline(dtype, op).unwrap();
                    assert_eq!(bit_field(r.trials[0].base, dtype, 4), 1);
                    assert_eq!(bit_field(r.trials[0].expected, dtype, 4), 2);
                }
                let r = baseline(dtype, Operation::Add).unwrap();
                assert_eq!(
                    bit_field(r.trials[0].expected, dtype, 3),
                    if dtype == DType::F64 { 0x3ff0_0000_0000_0001 } else { 0 }
                );
            }
        }
        assert_eq!(RECIPES.iter().filter(|r| !r.keys.is_empty()).count(), 16);
    }
    #[test]
    fn actual_initialized_base_and_every_physical_field_are_required() {
        for r in RECIPES.iter().filter(|r| !r.invalid) {
            for t in &r.trials {
                let good = guarded(t.expected);
                check_trial(r, t, &good).unwrap();
                for i in 0..r.parameters[3] as usize {
                    let mut bad = good.clone();
                    let at = 1 + i * r.dtype.size() / 4;
                    bad[at] ^= 1 << ((i * r.dtype.size() % 4) * 8);
                    assert!(check_trial(r, t, &bad).is_err());
                    if r.dtype.size() == 8 {
                        let mut high = good.clone();
                        high[at + 1] ^= 1;
                        assert!(check_trial(r, t, &high).is_err());
                    }
                }
                if !t.changed.is_empty() {
                    assert!(check_trial(r, t, &guarded(t.base)).is_err());
                }
                let mut bad = good.clone();
                bad[0] ^= 1;
                assert!(check_trial(r, t, &bad).is_err());
                let mut bad = good.clone();
                let last = bad.len() - 1;
                bad[last] ^= 1;
                assert!(check_trial(r, t, &bad).is_err());
                let tail = r.parameters[3] as usize * r.dtype.size() % 4;
                if tail != 0 {
                    let mut bad = good.clone();
                    let at = bad.len() - 2;
                    bad[at] ^= 1 << (tail * 8);
                    assert!(check_trial(r, t, &bad).is_err());
                }
            }
            // Poisoned-base expectations cannot be borrowed from trial zero.
            if r.trials[0].expected != r.trials[1].expected {
                assert!(check_trial(r, &r.trials[1], &guarded(r.trials[0].expected)).is_err());
            }
        }
        // Keep the full U64 payload while deliberately ordering by low words.
        // Each complete mutated output must fail in both initialized trials.
        for op in [Operation::Min, Operation::Max] {
            let r = baseline(DType::U64, op).unwrap();
            for trial in &r.trials {
                let mut wrong = trial.base.to_vec();
                for (position, &target) in r.indices.iter().enumerate() {
                    let target = target as usize;
                    let base = bit_field(&wrong, DType::U64, target);
                    let value = bit_field(r.values, DType::U64, position);
                    let take = if op == Operation::Min {
                        (value as u32) < (base as u32)
                    } else {
                        (value as u32) > (base as u32)
                    };
                    if take {
                        wrong[target * 2] = value as u32;
                        wrong[target * 2 + 1] = (value >> 32) as u32;
                    }
                }
                assert_ne!(wrong, trial.expected);
                assert!(check_trial(r, trial, &guarded(&wrong)).is_err());
            }
        }
    }
    #[test]
    fn no_match_fields_and_partial_words_preserve_provided_base_patterns() {
        for r in RECIPES {
            let live = r.parameters[3] as usize;
            for t in &r.trials {
                let changed: BTreeSet<_> = t.changed.iter().copied().collect();
                for field in 0..live {
                    assert_eq!(
                        changed.contains(&field),
                        bit_field(t.base, r.dtype, field) != bit_field(t.expected, r.dtype, field)
                    );
                }
                let bits = (live * r.dtype.size() % 4) * 8;
                if bits != 0 {
                    assert_eq!(t.base.last().unwrap() >> bits, t.expected.last().unwrap() >> bits);
                }
            }
        }
    }
    #[test]
    fn all_profile_slots_and_both_observers_are_checked() {
        let before = Snapshot {
            kernels: [abi::ProfileEntry::default(); abi::KERNEL_COUNT],
            services: [abi::ServiceEntry::default(); abi::SERVICE_OPERATIONS],
        };
        let mut after = before.clone();
        after.services[abi::PROFILE as usize].calls = 1;
        after.services[abi::SERVICE_PROFILE as usize].calls = 1;
        check_counters(&before, &after, &Work::default()).unwrap();
        for i in 0..abi::KERNEL_COUNT {
            let mut wrong = after.clone();
            wrong.kernels[i].calls += 1;
            assert!(check_counters(&before, &wrong, &Work::default()).is_err());
        }
        for i in 0..abi::SERVICE_OPERATIONS {
            let mut wrong = after.clone();
            wrong.services[i].calls += 1;
            assert!(check_counters(&before, &wrong, &Work::default()).is_err());
        }
        let mut read = after.clone();
        read.services[abi::DOWNLOAD as usize].calls += 1;
        check_counters(&before, &read, &Work::download()).unwrap();
        assert!(check_counters(&before, &read, &Work::default()).is_err());
        for (bytes, uploads) in [(0, 0), (1, 1), (2, 1), (3, 1), (4, 1), (5, 2), (6, 2), (7, 2), (8, 1), (30, 2), (510, 2)] {
            let mut expected = Work::upload();
            expected.services[abi::UPLOAD as usize] = uploads;
            assert_eq!(Work::packed_upload(bytes), expected);
        }
        let mut packed = after;
        packed.kernels[Kernel::Zero as usize].calls = 1;
        packed.services[abi::ALLOCATE as usize].calls = 1;
        packed.services[abi::UPLOAD as usize].calls = 2;
        check_counters(&before, &packed, &Work::packed_upload(30)).unwrap();
        assert!(check_counters(&before, &packed, &Work::upload()).is_err());
    }
    #[test]
    fn raw_empty_rejection_and_symbolic_aliases_precede_any_launch() {
        host_rejections().unwrap();
    }
    #[test]
    fn only_exact_semantic_and_metadata_errors_are_accepted() {
        for expected in [Error::InvalidParameter, Error::ShapeMismatch] {
            for actual in [
                Error::InvalidShape,
                Error::ShapeMismatch,
                Error::InvalidParameter,
                Error::SizeOverflow,
                Error::AllocationFailed,
                Error::NonFinite,
                Error::DeviceUnavailable,
                Error::DeviceFault,
            ] {
                assert_eq!(expect_error::<()>(Err(actual), expected).is_ok(), actual == expected);
            }
            assert!(expect_error(Ok(()), expected).is_err());
        }
    }
}
